const pct=c=>{const e=EN()[c.id];return e?Math.round(e.done.length/c.L.length*100):0};
const nextL=c=>{const e=EN()[c.id],k=c.L.findIndex((_,i)=>!e.done.includes(i));return k<0?0:k};
